  public static Dgraph.NodesValueResponse.Builder mergeNodesValueResponse(
      Dgraph.NodesValueResponse dst, Dgraph.NodesValueResponse src) {
    Dgraph.NodesValueResponse.Builder builder = dst.toBuilder();
    if (!dst.hasValue() && src.hasValue()) {
      builder.setValue(src.getValue());
    } else if (dst.hasValue() && src.hasValue()) {
      builder.setValue(mergeDgraphNode(dst.getValue(), src.getValue()).build());
    }
    if (!dst.getFound()) {
      builder.setFound(src.getFound());
    }
    return builder;
  }

  public static Dgraph.NodesEntriesResponse.Builder mergeNodesEntriesResponse(
      Dgraph.NodesEntriesResponse dst, Dgraph.NodesEntriesResponse src) {
    Dgraph.NodesEntriesResponse.Builder builder = dst.toBuilder();
    if (dst.getEntriesMap().isEmpty()) {
      builder.putAllEntries(src.getEntriesMap());
    } else {
      for (String mk : src.getEntriesMap().keySet()) {
        if (dst.getEntriesMap().containsKey(mk)) {
          builder.putEntries(
              mk,
              mergeDgraphNode(dst.getEntriesMap().get(mk), src.getEntriesMap().get(mk)).build());
        } else {
          builder.putEntries(mk, src.getEntriesMap().get(mk));
        }
      }
    }
    return builder;
  }

